"""Pricing helpers: bulk discounts, line totals, and SKU parsing."""

import re

_SKU_RE = re.compile(r"([A-Z]{2,4})-(\d{4})-([A-Z])")


def bulk_discount(qty):
    """Return the discount rate for an integer quantity.

    0.15 if qty >= 100, 0.05 if qty >= 20, otherwise 0.0.
    """
    if qty >= 100:
        return 0.15
    if qty >= 20:
        return 0.05
    return 0.0


def line_total(unit_price, qty):
    """Return unit_price * qty with the bulk discount applied, rounded to 2 decimals."""
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    """Parse a SKU of the form CAT-1234-X.

    Returns {"category": str, "number": int, "variant": str}.
    Raises ValueError if the SKU does not match.
    """
    m = _SKU_RE.fullmatch(s) if isinstance(s, str) else None
    if m is None:
        raise ValueError("invalid SKU: %r" % (s,))
    category, number, variant = m.groups()
    return {"category": category, "number": int(number), "variant": variant}

